   "answer": 3,
   "explain": "《中共中央关于全面深化改革若干重大问题的决定》是十八届三中全会通过的，故A 项错误。《中共中 央关于全面推进依法治国若干重大问题的决定》是十八届四中全会通过的，故B 项错误。“全面建成小康社会” 的战略目标是十八大提出的，故C 项错误。2014 年12 月，习近平总书记在江苏调研时将“三个全面”上升到了 “四个全面”，要“协调推进全面建成小康社会、全面深化改革、全面推进依法治国、全面从严治党，推动",
