   "answer": 1,
   "explain": "郦道元是南北朝时期北魏地理学家，撰有《水经注》四十卷，B 项将其对应“经济”是错误的。A 项， 白起是秦国名将，李靖是唐朝名将，对应“军事”是正确的。C 项，张衡发明了浑天仪，郭守敬制定了《授时 历》，对应“天文”是正确的。D 项，吴道子和顾恺之都是画家，对应“艺术”是正确的。 本题为选非题，故正确答案为 B。",
   "year": 2016,
   "exam_type": "gk-fsheng",
   "exam_volume": "行测",
   "topic": "",
   "src": "真题·PDF",
