   "answer": 3,
   "explain": "“权责法定”是指权力机关的权力和责任都由法律规定，即对权力机关而言，“法不授权不可为之”。 题干中“行政机关不得法外设定权力，没有法律法规依据不得……”正是体现了“法不授权不可为之”。 故正确答案为D。",
