   "answer": 0,
   "explain": "A 项《辛德勒名单》是澳大利亚小说家托马斯·肯尼利的作品，记录了德国企业家辛德勒“二战”期间 倾家荡产保护了1200 余名犹太人的故事，后由犹太人导演斯皮尔伯格拍成电影。 B 项《静静的顿河》是俄国天才作家肖洛霍夫的作品，记录的是1912—1922 年俄国特色群体——顿河地区 哥萨克人的生活，时间在“二战”之前。 C 项《智取威虎山》是记录解放战争时期解放军在东北剿匪的故事，时间在“二战”之后。",
