   "answer": 2,
   "explain": "辛亥革命爆发于1911 年10 月10 日；第一届世界杯是1930 年乌拉圭世界杯，故A 项不可能发生。 “五四”运动发生在1 9 1 9 年5 月4 日；半导体收音机是一种由二极管、三极管等电子器件组成的可 接收电信号并转成声音信号播出的一种电子设备，最早出现在1946 年，故B 项不可能发生。 冷战（1945—1990 年）简单来说就是以美国为首的西方集团（即北大西洋公约组织的成员国）和以苏联",
